CREATE TRIGGER [cache_dati_grafico_giornaliero_delete_trigger] ON [cache_dati_grafico_giornaliero] FOR DELETE AS
UPDATE [side] SET [sync_row_is_tombstone] = 1, [local_update_peer_key] = 0, [restore_timestamp] = NULL, [update_scope_local_id] = NULL, [last_change_datetime] = GETDATE() FROM [cache_dati_grafico_giornaliero_tracking] [side] JOIN DELETED AS [d] ON [side].[CodMac] = [d].[CodMac] AND [side].[DataRil] = [d].[DataRil]
